/**
 * Buildora design tokens — ships light + dark CSS vars so installed components
 * are styled on first paint instead of invisible. Import once in globals.css:
 *   @import "./styles/buildora/tokens.css";
 *
 * Semantic surface (--b-*) matches the @/styles/buildora/tokens package contract.
 * shadcn-parity aliases (--background/--primary/--border/--ring/--radius…)
 * let Buildora inherit a host theme when those are already defined.
 * Effect-only tokens live under --fx-*. Motion lives under --dur-* / --ease-*.
 */

:root,
[data-theme="light"] {
  --b-bg: #faf9f5;
  --b-panel: #ffffff;
  --b-surface: #f1efe9;
  --b-elevated: #ffffff;
  --b-border: rgba(19, 19, 22, 0.08);
  --b-border-hover: rgba(19, 19, 22, 0.18);
  --b-text: #131316;
  --b-text-secondary: #52525b;
  --b-muted: #727277;
  --b-ring: rgba(19, 19, 22, 0.16);
  --b-success: #006243;
  --b-warning: #963700;
  --b-danger: #ae0030;
  --b-accent: #376400;
  --b-accent-foreground: #ffffff;
  --b-accent-muted: rgba(55, 100, 0, 0.1);
  --b-iris: #493ddc;
  --b-iris-foreground: #ffffff;
  --b-radius: 12px;
  --b-radius-sm: 10px;
  --b-radius-lg: 16px;
  --b-transition: cubic-bezier(0.16, 1, 0.3, 1);
  --b-scrim: rgba(12, 10, 8, 0.42);
  color-scheme: light;

  /* shadcn-parity aliases so Buildora inherits the host theme */
  --background: var(--b-bg);
  --foreground: var(--b-text);
  --card: var(--b-panel);
  --popover: var(--b-panel);
  --primary: var(--b-accent);
  --primary-foreground: var(--b-accent-foreground);
  --secondary: var(--b-surface);
  --secondary-foreground: var(--b-text);
  --muted: var(--b-surface);
  --muted-foreground: var(--b-muted);
  --accent: var(--b-surface);
  --accent-foreground: var(--b-text);
  --destructive: var(--b-danger);
  --border: var(--b-border);
  --input: var(--b-border);
  --ring: var(--b-ring);
  --radius: var(--b-radius);
}

[data-theme="dark"] {
  --b-bg: #050507;
  --b-panel: #0a0a0e;
  --b-surface: #101015;
  --b-elevated: #16161c;
  --b-border: rgba(255, 255, 255, 0.06);
  --b-border-hover: rgba(255, 255, 255, 0.18);
  --b-text: #ededf0;
  --b-text-secondary: #a5a5b2;
  --b-muted: #767684;
  --b-ring: rgba(255, 255, 255, 0.16);
  --b-success: #34d399;
  --b-warning: #fbbf24;
  --b-danger: #fe7487;
  --b-accent: #ccff00;
  --b-accent-foreground: #131305;
  --b-accent-muted: rgba(204, 255, 0, 0.12);
  --b-iris: #8b97ff;
  --b-iris-foreground: #10102a;
  --b-scrim: rgba(0, 0, 0, 0.62);
  color-scheme: dark;

  --background: var(--b-bg);
  --foreground: var(--b-text);
  --card: var(--b-panel);
  --popover: var(--b-panel);
  --primary: var(--b-accent);
  --primary-foreground: var(--b-accent-foreground);
  --secondary: var(--b-surface);
  --secondary-foreground: var(--b-text);
  --muted: var(--b-surface);
  --muted-foreground: var(--b-muted);
  --accent: var(--b-surface);
  --accent-foreground: var(--b-text);
  --destructive: var(--b-danger);
  --border: var(--b-border);
  --input: var(--b-border);
  --ring: var(--b-ring);
}

/* ── Terminal skin ──────────────────────────────────────────────────
   One theme, not seventeen components. Apply it to any ancestor:

     <div data-theme="terminal">…</div>

   Every Buildora primitive reads the same --b-* vars, so this restyles
   buttons, inputs, badges, tables and tabs at once. Radii are squared and
   the type goes monospace; the semantics do not change. */
[data-theme="terminal"] {
  --b-bg: #0a0a0a;
  --b-panel: #101010;
  --b-surface: #161616;
  --b-elevated: #1c1c1c;
  --b-border: rgba(255, 255, 255, 0.14);
  --b-border-hover: rgba(255, 255, 255, 0.26);
  --b-text: #d7d7d7;
  --b-text-secondary: #a0a0a0;
  --b-muted: #7a7a7a;
  --b-ring: rgba(212, 255, 79, 0.45);
  --b-success: #56d364;
  --b-warning: #e3b341;
  --b-danger: #ff695e;
  --b-accent: #d4ff4f;
  --b-accent-foreground: #0a0a0a;
  --b-accent-muted: rgba(212, 255, 79, 0.14);
  --b-iris: #79c0ff;
  --b-iris-foreground: #0a0a0a;
  --b-radius: 0px;
  --b-radius-sm: 0px;
  --b-radius-lg: 0px;
  --b-glass: rgba(16, 16, 16, 0.9);
  --b-glass-border: rgba(255, 255, 255, 0.16);
  --b-scrim: rgba(0, 0, 0, 0.72);
  --b-font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  color-scheme: dark;
}

/* Square off the primitives that carry their own radius classes. */
[data-theme="terminal"] :is(button, input, textarea, select, [role="dialog"], [role="menu"], [role="listbox"]) {
  border-radius: 0;
}

[data-theme="terminal"] :is(button, input, textarea, select, [role="dialog"], [role="menu"], [role="listbox"]) {
  font-family: var(--b-font-mono);
}

/* Layering + motion vocabulary shared by every primitive */
:root {
  --z-dropdown: 50;
  --z-overlay: 100;
  --z-toast: 150;
  --z-cursor: 200;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-fast: 140ms;
  --dur-base: 220ms;
  --dur-slow: 420ms;
}

@media (forced-colors: active) {
  :root {
    --b-border: CanvasText;
    --b-text: CanvasText;
    --b-bg: Canvas;
    --b-panel: Canvas;
    forced-color-adjust: auto;
  }
}

/* Shared keyframes (replaces per-component <style jsx> blocks) */
@keyframes buildora-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes buildora-fade-out {
  from { opacity: 1; }
  to { opacity: 0; }
}
@keyframes buildora-scale-in {
  from { opacity: 0; transform: scale(0.95) translateY(10px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}
@keyframes buildora-scale-out {
  from { opacity: 1; transform: scale(1) translateY(0); }
  to { opacity: 0; transform: scale(0.95) translateY(10px); }
}
@keyframes buildora-shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
@keyframes buildora-marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes buildora-meteor {
  0% { transform: translate(0, 0) rotate(-45deg); opacity: 0; }
  10% { opacity: 1; }
  100% { transform: translate(-40vw, 40vh) rotate(-45deg); opacity: 0; }
}
@keyframes buildora-drift-a {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(8%, 12%) scale(1.08); }
}
@keyframes buildora-beam-sweep {
  from { transform: translateX(-70%); }
  to { transform: translateX(70%); }
}
@keyframes buildora-beam-rise {
  0% { transform: translateY(15%); opacity: 0; }
  12% { opacity: 1; }
  88% { opacity: 1; }
  100% { transform: translateY(-260%); opacity: 0; }
}
@keyframes buildora-ripple-expand {
  from { transform: scale(0.4); opacity: 0.7; }
  to { transform: scale(1.6); opacity: 0; }
}
@keyframes buildora-gradient-pan {
  from { background-position: 0% 50%; }
  to { background-position: 200% 50%; }
}
@keyframes buildora-gradient-shift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes buildora-ripple-dot {
  from { transform: translate(-50%, -50%) scale(0); opacity: 0.9; }
  to { transform: translate(-50%, -50%) scale(18); opacity: 0; }
}
@keyframes buildora-glitch-a {
  0%, 100% { clip-path: inset(40% 0 60% 0); opacity: 0.5; }
  20% { clip-path: inset(92% 0 1% 0); opacity: 0.7; }
  40% { clip-path: inset(43% 0 1% 0); opacity: 0.3; }
  60% { clip-path: inset(25% 0 58% 0); opacity: 0.6; }
  80% { clip-path: inset(54% 0 7% 0); opacity: 0.4; }
}
@keyframes buildora-glitch-b {
  0%, 100% { clip-path: inset(50% 0 30% 0); opacity: 0.6; }
  20% { clip-path: inset(7% 0 85% 0); opacity: 0.4; }
  40% { clip-path: inset(89% 0 3% 0); opacity: 0.7; }
  60% { clip-path: inset(23% 0 69% 0); opacity: 0.5; }
  80% { clip-path: inset(2% 0 91% 0); opacity: 0.3; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
